class Solution {
public:
    bool isThree(int n) {
        int cnt = 0;
        for (long long d = 1; d * d <= n; ++d) {
            if (n % d == 0) {
                cnt += (d * d == n) ? 1 : 2;
                if (cnt > 3) return false;
            }
        }
        return cnt == 3;
    }
};

