class Solution {
public:
    bool isThree(int n) {
        int r = (int) sqrt((double) n);
        if ((long long) r * r != n || r < 2) return false;
        for (int i = 2; i * i <= r; ++i)
            if (r % i == 0) return false;
        return true;
    }
};

